{#- Code generated by packages/kit-compose/src/server-organisms.ts from packages/compose-gen/specs (compose-gen organism emitters on kit-compose). DO NOT EDIT.
    Source: packages/compose-gen/specs/organisms/feature-cards.json
    The features as a grid of cards, tiles or bordered cells (the body of FeatureGrid). Icons are Lucide names.
    Props (p): features, cols, item. -#}
{%- set v_features = (p.features ?? null) -%}
{%- set v_cols = (p.cols ?? '1-3') -%}
{%- set v_item = (p.item ?? 'card') -%}
{%- set c_15 -%}
  {%- for v_feature in og_l(v_features) %}
    {%- if og_t(og_eq(v_item, 'tile')) %}
      {%- set c_5 -%}
        {%- set c_4 -%}
          {{ include('icons/LucideIcon.html.twig', {'name': og_s(og_get(v_feature, ['icon'])), 'size': 20}, with_context = false) }}
          {%- set c_3 -%}
            {%- set c_1 -%}
              {{ og_text(og_get(v_feature, ['title'])) }}
            {%- endset -%}
            {{ include('compose/Title.html.twig', {'as': 3, 'size': 'base', 'weight': 'bold', 'children': c_1}, with_context = false) }}
            {%- set c_2 -%}
              {{ og_text(og_get(v_feature, ['text'])) }}
            {%- endset -%}
            {{ include('compose/Text.html.twig', {'size': 'sm', 'class': 'text-muted-foreground', 'children': c_2}, with_context = false) }}
          {%- endset -%}
          {{ include('compose/Stack.html.twig', {'gap': '2', 'children': c_3}, with_context = false) }}
        {%- endset -%}
        {{ include('compose/Group.html.twig', {'gap': '4', 'align': 'start', 'children': c_4}, with_context = false) }}
      {%- endset -%}
      {{ include('compose/Card.html.twig', {'variant': 'compact', 'attrs': og_attrs(['data-testid', 'feature-card']), 'children': c_5}, with_context = false) }}
    {%- elseif og_t(og_eq(v_item, 'cell')) %}
      {%- set c_9 -%}
        {%- set c_6 -%}
          {{ include('icons/LucideIcon.html.twig', {'name': og_s(og_get(v_feature, ['icon'])), 'size': 24}, with_context = false) }}
        {%- endset -%}
        {{ include('compose/IconBadge.html.twig', {'variant': 'primary', 'size': 'xl', 'attrs': og_attrs(['data-testid', 'feature-icon']), 'children': c_6}, with_context = false) }}
        {%- set c_7 -%}
          {{ og_text(og_get(v_feature, ['title'])) }}
        {%- endset -%}
        {{ include('compose/Title.html.twig', {'as': 3, 'size': 'xl', 'weight': 'semibold', 'class': 'leading-6', 'children': c_7}, with_context = false) }}
        {%- set c_8 -%}
          {{ og_text(og_get(v_feature, ['text'])) }}
        {%- endset -%}
        {{ include('compose/Text.html.twig', {'size': 'sm', 'weight': 'semibold', 'class': 'leading-5 text-muted-foreground', 'children': c_8}, with_context = false) }}
      {%- endset -%}
      {{ include('compose/Stack.html.twig', {'gap': '2', 'align': 'center', 'class': 'h-full gap-8 bg-background px-6 py-12 text-center', 'attrs': og_attrs(['data-testid', 'feature-card']), 'children': c_9}, with_context = false) }}
    {%- else %}
      {%- set c_14 -%}
        {%- set c_11 -%}
          {{ include('icons/LucideIcon.html.twig', {'name': og_s(og_get(v_feature, ['icon'])), 'size': 24}, with_context = false) }}
          {%- set c_10 -%}
            {{ og_text(og_get(v_feature, ['title'])) }}
          {%- endset -%}
          {{ include('compose/CardTitle.html.twig', {'as': 3, 'children': c_10}, with_context = false) }}
        {%- endset -%}
        {{ include('compose/CardHeader.html.twig', {'class': 'flex flex-col gap-4', 'children': c_11}, with_context = false) }}
        {%- set c_13 -%}
          {%- set c_12 -%}
            {{ og_text(og_get(v_feature, ['text'])) }}
          {%- endset -%}
          {{ include('compose/Text.html.twig', {'size': 'sm', 'class': 'text-muted-foreground', 'children': c_12}, with_context = false) }}
        {%- endset -%}
        {{ include('compose/CardContent.html.twig', {'children': c_13}, with_context = false) }}
      {%- endset -%}
      {{ include('compose/Card.html.twig', {'variant': 'default', 'attrs': og_attrs(['data-testid', 'feature-card']), 'children': c_14}, with_context = false) }}
    {%- endif %}
  {%- endfor %}
{%- endset -%}
{{ include('compose/Grid.html.twig', {'cols': og_s(v_cols), 'class': og_s((og_t(og_eq(v_item, 'cell')) ? og_cnv(['w-full gap-px overflow-hidden bg-border p-px', og_preset('blocks/presets/defaults.json', ['features', 'cells'])]) : 'gap-6')), 'attrs': og_attrs(['data-testid', 'feature-grid']), 'children': c_15}, with_context = false) }}
